package cn.zhuatech.supplyai.controller; import cn.zhuatech.supplyai.common.ApiResponse; import cn.zhuatech.supplyai.dto.SupplyAiDto.*; import cn.zhuatech.supplyai.service.SupplyAiService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final SupplyAiService service;public OperationsAdminController(SupplyAiService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
